<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

  html, body {
    width: 100%; height: 100%;
    overflow: hidden;
    font-family: 'Ubuntu', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
    background: #0f0f23;
    color: #eceff4;
    user-select: none;
  }

  /* ─── Desktop ─── */
  #desktop {
    position: relative;
    width: 100vw; height: 100vh;
    background: linear-gradient(135deg, #2c001e 0%, #4a0030 30%, #1b2838 60%, #0f0f23 100%);
    overflow: hidden;
  }

  /* wallpaper hint */
  #desktop::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at 70% 40%, rgba(236,116,59,.12) 0%, transparent 60%),
                radial-gradient(ellipse at 30% 70%, rgba(85,100,180,.10) 0%, transparent 50%);
    pointer-events: none;
    z-index: 0;
  }

  /* ─── Top Bar ─── */
  #topbar {
    position: absolute; top: 0; left: 0; right: 0;
    height: 28px;
    background: rgba(20,20,35,.95);
    backdrop-filter: blur(8px);
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 14px;
    font-size: 13px; color: #eceff4;
    z-index: 900;
    border-bottom: 1px solid rgba(255,255,255,.06);
  }
  #topbar .left { display: flex; align-items: center; gap: 18px; }
  #topbar .right { display: flex; align-items: center; gap: 14px; opacity: .85; font-size: 12.5px; }

  /* ─── Dock / Taskbar ─── */
  #taskbar {
    position: absolute;
    bottom: 10px;
    left: 50%; transform: translateX(-50%);
    display: flex; align-items: center; gap: 6px;
    background: rgba(22,22,40,.92);
    backdrop-filter: blur(14px);
    border-radius: 16px;
    padding: 8px 14px;
    z-index: 800;
    box-shadow: 0 4px 30px rgba(0,0,0,.45);
    border: 1px solid rgba(255,255,255,.07);
  }

  #taskbar button {
    background: rgba(255,255,255,.06);
    color: #eceff4;
    border: none;
    border-radius: 12px;
    padding: 8px 18px;
    font-size: 13px;
    cursor: pointer;
    transition: background .15s, transform .1s;
    white-space: nowrap;
    display: flex; align-items: center; gap: 6px;
  }
  #taskbar button:hover { background: rgba(255,255,255,.13); }
  #taskbar button:active { transform: scale(.96); }

  .dock-icon {
    width: 20px; height: 20px; display: inline-block;
    border-radius: 4px; flex-shrink: 0;
  }
  .icon-files { background: linear-gradient(135deg,#f0a500,#e67e22); }
  .icon-notepad { background: linear-gradient(135deg,#5e81ac,#88c0d0); }

  /* ─── Window base ─── */
  .app-window {
    position: absolute;
    min-width: 360px; min-height: 240px;
    background: #1e1e2e;
    border-radius: 10px;
    box-shadow: 0 8px 40px rgba(0,0,0,.55), 0 0 0 1px rgba(255,255,255,.06);
    display: none; flex-direction: column;
    z-index: 700;
    overflow: hidden;
  }
  .app-window.visible { display: flex; }

  .win-titlebar {
    height: 38px;
    background: #252538;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 10px;
    border-bottom: 1px solid rgba(255,255,255,.06);
    cursor: default;
    flex-shrink: 0;
  }
  .win-titlebar .title {
    font-size: 13px; font-weight: 600; opacity: .8;
    pointer-events: none;
  }
  .win-controls { display: flex; gap: 7px; align-items: center; }
  .win-close {
    width: 22px; height: 22px;
    border-radius: 50%;
    background: #e95450;
    border: none; color: #fff; font-size: 13px; line-height: 1;
    cursor: pointer; display: flex; align-items: center; justify-content: center;
    opacity: .85; transition: opacity .12s;
  }
  .win-close:hover { opacity: 1; }

  /* ─── Files app ─── */
  #files-window { min-width: 460px; min-height: 340px; width: 700px; height: 480px; top: 50%; left: 50%; transform: translate(-50%,-50%); }

  #files-toolbar {
    display: flex; align-items: center; gap: 8px; padding: 8px 12px;
    background: #2a2a3d; border-bottom: 1px solid rgba(255,255,255,.05);
  }
  #files-up {
    background: rgba(255,255,255,.07); color: #eceff4; border: none;
    border-radius: 6px; padding: 5px 12px; cursor: pointer; font-size: 13px;
    display: flex; align-items: center; gap: 4px;
  }
  #files-up:hover { background: rgba(255,255,255,.13); }
  #files-path {
    flex: 1; text-align: center; font-size: 13px; opacity: .7;
    background: rgba(0,0,0,.18); border-radius: 6px; padding: 5px 10px;
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  }

  #files-content {
    flex: 1; padding: 12px; overflow-y: auto;
    display: flex; flex-wrap: wrap; gap: 8px; align-content: flex-start;
  }
  .fs-item {
    width: 90px; display: flex; flex-direction: column; align-items: center;
    padding: 10px 4px; border-radius: 8px; cursor: default; gap: 6px;
    transition: background .12s;
  }
  .fs-item:hover { background: rgba(255,255,255,.07); }
  .fs-item.folder { cursor: pointer; }
  .fs-item.folder:hover { outline: 1px solid rgba(255,255,255,.15); }
  .fs-icon { font-size: 36px; line-height: 1; }
  .fs-name { font-size: 11.5px; text-align: center; word-break: break-all; opacity: .9; }

  /* ─── Notepad app ─── */
  #notepad-window { min-width: 460px; min-height: 340px; width: 720px; height: 500px; top: 55%; left: 55%; transform: translate(-50%,-50%); }

  #notepad-toolbar {
    display: flex; align-items: center; gap: 8px; padding: 6px 12px;
    background: #2a2a3d; border-bottom: 1px solid rgba(255,255,255,.05);
  }
  #new-tab {
    background: rgba(255,255,255,.07); color: #eceff4; border: none;
    border-radius: 6px; padding: 5px 14px; cursor: pointer; font-size: 13px;
  }
  #new-tab:hover { background: rgba(255,255,255,.14); }

  #tabs {
    display: flex; align-items: center; gap: 0; padding: 0 8px;
    background: #2a2a3d; border-bottom: 1px solid rgba(255,255,255,.05);
    overflow-x: auto; min-height: 34px; flex-shrink: 0;
  }
  .tab {
    padding: 7px 16px; font-size: 12.5px; cursor: pointer;
    border-right: 1px solid rgba(255,255,255,.06);
    background: transparent; color: #eceff4; opacity: .55;
    white-space: nowrap; display: flex; align-items: center; gap: 6px;
    transition: opacity .12s, background .12s;
    border-radius: 0;
  }
  .tab:hover { opacity: .8; background: rgba(255,255,255,.04); }
  .tab.active { opacity: 1; background: rgba(255,255,255,.06); font-weight: 600; }
  .tab .close-tab {
    width: 16px; height: 16px; border-radius: 50%; border: none;
    background: transparent; color: inherit; cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    font-size: 11px; opacity: .5;
  }
  .tab .close-tab:hover { opacity: 1; background: rgba(233,84,80,.4); color: #fff; }

  #editor-wrap { flex: 1; display: flex; flex-direction: column; overflow: hidden; }
  #editor {
    flex: 1; width: 100%; resize: none; border: none; outline: none;
    background: #1a1a2e; color: #d8dee9; font-family: 'Ubuntu Mono', 'Fira Code', 'Consolas', monospace;
    font-size: 14px; padding: 14px; line-height: 1.6; tab-size: 4;
  }
</style>
</head>
<body>

<!-- ─── Desktop Root ─── -->
<div id="desktop">

  <!-- Top Bar -->
  <div id="topbar">
    <div class="left">
      <span style="font-weight:700;letter-spacing:.5px;">Files</span>
      <span style="cursor:pointer;">Notepad</span>
      <span style="cursor:pointer;">Terminal</span>
    </div>
    <div class="right">
      <span id="clock"></span>
    </div>
  </div>

  <!-- Dock / Taskbar -->
  <div id="taskbar">
    <button id="open-files">
      <span class="dock-icon icon-files"></span> Files
    </button>
    <button id="open-notepad">
      <span class="dock-icon icon-notepad"></span> Notepad
    </button>
  </div>

  <!-- ═══ Files Window ═══ -->
  <div id="files-window" class="app-window">
    <div class="win-titlebar">
      <span class="title">File Manager</span>
      <div class="win-controls"><button class="win-close" title="Close">&times;</button></div>
    </div>
    <div id="files-toolbar">
      <button id="files-up">↑ Up</button>
      <span id="files-path">/</span>
    </div>
    <div id="files-content"></div>
  </div>

  <!-- ═══ Notepad Window ═══ -->
  <div id="notepad-window" class="app-window">
    <div class="win-titlebar">
      <span class="title">Text Editor</span>
      <div class="win-controls"><button class="win-close" title="Close">&times;</button></div>
    </div>
    <div id="notepad-toolbar">
      <button id="new-tab">+ New Tab</button>
    </div>
    <div id="tabs"></div>
    <div id="editor-wrap">
      <textarea id="editor" spellcheck="false"></textarea>
    </div>
  </div>

</div>

<script>
/* ─── Clock ─── */
(function clock(){
  var el = document.getElementById('clock');
  function tick(){
    var d=new Date();
    el.textContent = d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
  }
  tick(); setInterval(tick,10000);
})();

/* ─── Helpers ─── */
var activeWin = null; // track z-ordering

function bringToFront(w){
  var maxZ = 700;
  document.querySelectorAll('.app-window.visible').forEach(function(w2){
    if(parseInt(w2.style.zIndex||0) > maxZ) maxZ = parseInt(w2.style.zIndex);
  });
  w.style.zIndex = maxZ + 1;
}

/* ════════════════════════════════════════
   FILE MANAGER
   ════════════════════════════════════════ */

var fileSystem = {
  '/':        ['bin','etc','home','usr','var'],
  '/bin':     ['bash','ls','cat','cp','mv','rm','mkdir','cd','grep','sed'],
  '/etc':     ['passwd','hostname','resolv.conf','fstab','hostnamectl'],
  '/home':    ['user'],
  '/home/user':['Documents','Downloads','Pictures','Music','Videos','.bashrc','.profile','Desktop'],
  '/home/user/Documents':['report.txt','notes.md','todo.org'],
  '/home/user/Downloads':['ubuntu-24.04.iso','archive.tar.gz'],
  '/home/user/Pictures':['wallpaper.png','screenshot.png'],
  '/home/user/Music':[],
  '/home/user/Videos':[],
  '/usr':     ['bin','lib','share','local'],
  '/usr/bin': ['python3','gcc','git','node','npm'],
  '/var':     ['log','tmp','cache'],
  '/var/log':['syslog','auth.log'],
  '/var/tmp':[],
  '/var/cache':[]
};

// Ensure any path we might navigate to has a key (empty array)
function ensurePath(p){ if(!fileSystem[p]) fileSystem[p] = []; }

(function(){
  var currentPath = '/';
  var contentEl   = document.getElementById('files-content');
  var pathEl      = document.getElementById('files-path');

  function isFolder(name){ return true; } // everything listed is a folder in our fake fs

  function render(){
    ensurePath(currentPath);
    contentEl.innerHTML = '';
    pathEl.textContent = currentPath || '/';

    if(currentPath !== '/'){
      // Up button already exists via #files-up
    }

    var entries = fileSystem[currentPath] || [];
    // Sort: folders first (already are), then alpha
    entries.sort();

    if(entries.length === 0){
      var empty = document.createElement('div');
      empty.style.cssText = 'width:100%;text-align:center;opacity:.35;font-size:13px;padding:40px 0;';
      empty.textContent = '(empty folder)';
      contentEl.appendChild(empty);
    }

    entries.forEach(function(name){
      var el = document.createElement('div');
      el.className = 'fs-item folder';

      var icon = document.createElement('span');
      icon.className = 'fs-icon';
      // Different icons for dirs vs files
      icon.textContent = '\uD83D\uDCC2'; // folder emoji
      if(name.indexOf('.') !== -1 && name.lastIndexOf('.') > 0){
        icon.textContent = '\uD83D\uDCC4';
      }

      var label = document.createElement('span');
      label.className = 'fs-name';
      label.textContent = name;

      el.appendChild(icon);
      el.appendChild(label);

      // double-click to navigate
      el.addEventListener('dblclick', function(e){
        e.preventDefault();
        var newPath = currentPath === '/' ? '/' + name : currentPath + '/' + name;
        currentPath = newPath;
        ensurePath(currentPath);
        render();
      });

      contentEl.appendChild(el);
    });
  }

  // up navigation
  document.getElementById('files-up').addEventListener('click', function(){
    if(currentPath !== '/'){
      var parts = currentPath.split('/').filter(Boolean);
      parts.pop();
      currentPath = '/' + parts.join('/') || '/';
      render();
    }
  });

  render();
})();


/* ════════════════════════════════════════
   NOTEPAD  (tabbed, localStorage-persisted)
   ════════════════════════════════════════ */

(function(){
  var STORAGE_KEY = 'ubuntu-notepad-tabs';

  function loadTabs(){
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
    catch(e){ return []; }
  }
  function saveTabs(){
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tabs));
  }

  var tabs = loadTabs();
  if(tabs.length === 0){
    tabs = [{ id: genId(), name:'Untitled', content:'' }];
  }
  var activeIdx = Math.max(0, tabs.findIndex(function(t){return t.active;}));
  if(activeIdx < 0 || activeIdx >= tabs.length) activeIdx = 0;

  function genId(){ return 'tab_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2,5); }

  var editorEl = document.getElementById('editor');
  var tabsEl   = document.getElementById('tabs');
  var newTabBtn= document.getElementById('new-tab');

  function renderTabs(){
    tabsEl.innerHTML = '';
    tabs.forEach(function(t,i){
      var el = document.createElement('div');
      el.className = 'tab' + (i === activeIdx ? ' active' : '');
      el.setAttribute('data-idx', i);

      var nameSpan = document.createElement('span');
      nameSpan.textContent = t.name;
      el.appendChild(nameSpan);

      // close button on tab
      if(tabs.length > 1){
        var cbtn = document.createElement('button');
        cbtn.className = 'close-tab';
        cbtn.innerHTML = '&times;';
        cbtn.title = 'Close tab';
        (function(idx2){
          cbtn.addEventListener('click', function(e2){
            e2.stopPropagation();
            closeTab(idx2);
          });
        })(i);
        el.appendChild(cbtn);
      }

      (function(idx2){
        el.addEventListener('click', function(){ switchTo(idx2); });
      })(i);

      tabsEl.appendChild(el);
    });
  }

  function updateEditor(){
    editorEl.value = tabs[activeIdx].content;
  }

  function switchTo(idx){
    activeIdx = idx;
    renderTabs();
    updateEditor();
  }

  function newTab(){
    var t = { id: genId(), name:'Untitled', content:'' };
    tabs.push(t);
    activeIdx = tabs.length - 1;
    saveTabs();
    renderTabs();
    updateEditor();
    editorEl.focus();
  }

  function closeTab(idx){
    if(tabs.length <= 1) return;
    tabs.splice(idx, 1);
    if(activeIdx >= tabs.length) activeIdx = tabs.length - 1;
    saveTabs();
    renderTabs();
    updateEditor();
  }

  editorEl.addEventListener('input', function(){
    tabs[activeIdx].content = editorEl.value;
    saveTabs();
  });

  newTabBtn.addEventListener('click', newTab);

  // expose to global for persistence
  window._notepadState = { get tabs(){ return tabs; }, set tabs(v){ tabs=v; } };

  renderTabs();
  updateEditor();
})();


/* ════════════════════════════════════════
   WINDOW OPEN / CLOSE
   ════════════════════════════════════════ */

(function(){
  var filesWin = document.getElementById('files-window');
  var notepadWin = document.getElementById('notepad-window');

  // open buttons
  document.getElementById('open-files').addEventListener('click', function(){
    filesWin.classList.add('visible');
    bringToFront(filesWin);
  });
  document.getElementById('open-notepad').addEventListener('click', function(){
    notepadWin.classList.add('visible');
    bringToFront(notepadWin);
  });

  // close buttons
  filesWin.querySelector('.win-close').addEventListener('click', function(){
    filesWin.classList.remove('visible');
  });
  notepadWin.querySelector('.win-close').addEventListener('click', function(){
    notepadWin.classList.remove('visible');
  });

  // click window to bring to front
  [filesWin, notepadWin].forEach(function(w){
    w.addEventListener('mousedown', function(){ bringToFront(w); });
  });
})();


/* ════════════════════════════════════════
   SAVE NOTEPAD BEFORE UNLOAD
   ════════════════════════════════════════ */

(function(){
  // Already handled by input listener, but ensure on unload too
  window.addEventListener('beforeunload', function(){
    try{
      localStorage.setItem('ubuntu-notepad-tabs', JSON.stringify(window._notepadState.tabs));
    }catch(e){}
  });
})();

</script>
</body>
</html>
